/* @lc app=leetcode id=3144 lang=kotlin */ class Solution { fun minimumSubstringsInPartition(s: String): Int = (1..s.length).fold(listOf(0)) { dp, i -> dp + IntArray(26).let { f -> (i - 1 downTo 0).fold(Int.MAX_VALUE) { best, j -> (++f[s[j] - 'a']).let { (i - j).let { len -> if (f.max() * f.count { it > 0 } == len && dp[j] != Int.MAX_VALUE) minOf(best, dp[j] + 1) else best } } } } }.last() }